import{_ as p,a0 as r,w as d,s as o,ao as l,I as a,x as n,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 Ubuntu 以及 Debian 中安装 DHCP 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 以及 Debian 中安装 DHCP 服务器 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 以及 Debian 中安装 DHCP 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 以及 Debian 中安装 DHCP 服务器 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170325 How to Install a DHCP Server in Ubuntu and Debian","title":"如何在 Ubuntu 以及 Debian 中安装 DHCP 服务器","tag":"201703","desc":""},"relativePath":"201703/20170325 How to Install a DHCP Server in Ubuntu and Debian.md","filePath":"[post].md"}'),u={name:"201703/20170325 How to Install a DHCP Server in Ubuntu and Debian.md"};function h(g,s,b,c,k,C){const e=r("Link");return d(),o("div",null,[s[20]||(s[20]=l('<h1 id="如何在-ubuntu-以及-debian-中安装-dhcp-服务器" tabindex="-1">如何在 Ubuntu 以及 Debian 中安装 DHCP 服务器 <a class="header-anchor" href="#如何在-ubuntu-以及-debian-中安装-dhcp-服务器" aria-label="Permalink to “如何在 Ubuntu 以及 Debian 中安装 DHCP 服务器”">​</a></h1><p><strong>动态主机配置协议（DHCP）</strong> 是一种用于使主机能够从服务器自动分配 IP 地址和相关的网络配置的网络协议。</p><p>DHCP 服务器分配给 DHCP 客户端的 IP 地址处于“租用”状态，租用时间通常取决于客户端计算机要求连接的时间或 DHCP 服务器配置的时间。</p><h4 id="dhcp-如何工作" tabindex="-1">DHCP 如何工作？ <a class="header-anchor" href="#dhcp-如何工作" aria-label="Permalink to “DHCP 如何工作？”">​</a></h4><p>以下是 DHCP 实际工作原理的简要说明：</p><ul><li>一旦客户端（配置为使用 DHCP 的机器）连接到网络后，它会向 DHCP 服务器发送 <strong>DHCPDISCOVER</strong> 数据包。</li><li>当 DHCP 服务器收到 <strong>DHCPDISCOVER</strong> 请求报文后会使用 <strong>DHCPOFFER</strong> 包进行回复。</li><li>然后客户端获取到 <strong>DHCPOFFER</strong> 数据包，并向服务器发送一个 <strong>DHCPREQUEST</strong> 包，表示它已准备好接收 <strong>DHCPOFFER</strong> 包中提供的网络配置信息。</li><li>最后，DHCP 服务器从客户端收到 <strong>DHCPREQUEST</strong> 报文后，发送 <strong>DHCPACK</strong> 报文，表示现在允许客户端使用分配给它的 IP 地址。</li></ul>',6)),a("p",null,[s[1]||(s[1]=n("在本文中，我们将介绍如何在 Ubuntu/Debian Linux 中设置 DHCP 服务器，我们将使用 ",-1)),i(e,{href:"https://linux.cn/tag-sudo.html"},{default:t(()=>[...s[0]||(s[0]=[n("sudo 命令",-1)])]),_:1}),s[2]||(s[2]=n("来运行所有命令，以获得 root 用户权限。",-1))]),s[21]||(s[21]=l('<h3 id="测试环境设置" tabindex="-1">测试环境设置 <a class="header-anchor" href="#测试环境设置" aria-label="Permalink to “测试环境设置”">​</a></h3><p>在这步中我们会使用如下的测试环境。</p><ul><li>DHCP Server - Ubuntu 16.04</li><li>DHCP Clients - CentOS 7 and Fedora 25</li></ul><h3 id="步骤-1-在-ubuntu-中安装-dhcp-服务器" tabindex="-1">步骤 1：在 Ubuntu 中安装 DHCP 服务器 <a class="header-anchor" href="#步骤-1-在-ubuntu-中安装-dhcp-服务器" aria-label="Permalink to “步骤 1：在 Ubuntu 中安装 DHCP 服务器”">​</a></h3><p>1、 运行下面的命令来安装 DHCP 服务器包，也就是 <strong>dhcp3-server</strong>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install isc-dhcp-server</span></span></code></pre></div><p>2、 安装完成后，编辑 <code>/etc/default/isc-dhcp-server</code> 使用 <code>INTERFACES</code> 选项定义 DHCPD 响应 DHCP 请求所使用的接口。</p><p>比如，如果你想让 DHCPD 守护进程监听 <code>eth0</code>，按如下设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>INTERFACES=&quot;eth0&quot;</span></span></code></pre></div>',9)),a("p",null,[s[4]||(s[4]=n("同样记得为上面的接口",-1)),i(e,{href:"http://www.tecmint.com/set-add-static-ip-address-in-linux/"},{default:t(()=>[...s[3]||(s[3]=[n("配置静态地址",-1)])]),_:1}),s[5]||(s[5]=n("。",-1))]),s[22]||(s[22]=l(`<h3 id="步骤-2-在-ubuntu-中配置-dhcp-服务器" tabindex="-1">步骤 2：在 Ubuntu 中配置 DHCP 服务器 <a class="header-anchor" href="#步骤-2-在-ubuntu-中配置-dhcp-服务器" aria-label="Permalink to “步骤 2：在 Ubuntu 中配置 DHCP 服务器”">​</a></h3><p>3、 DHCP 配置的主文件是 <code>/etc/dhcp/dhcpd.conf</code>， 你必须填写会发送到客户端的所有网络信息。</p><p>并且 DHCP 配置中定义了两种不同的声明，它们是：</p><ul><li><code>parameters</code> - 指定如何执行任务、是否执行任务，还有指定要发送给 DHCP 客户端的网络配置选项。</li><li><code>declarations</code> - 定义网络拓扑、指定客户端、为客户端提供地址，或将一组参数应用于一组声明。</li></ul><p>4、 现在打开并修改主文件，定义 DHCP 服务器选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/dhcp/dhcpd.conf</span></span></code></pre></div><p>在文件顶部设置以下全局参数，它们将应用于下面的所有声明（请指定适用于你情况的值）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>option domain-name &quot;tecmint.lan&quot;;</span></span>
<span class="line"><span>option domain-name-servers ns1.tecmint.lan, ns2.tecmint.lan;</span></span>
<span class="line"><span>default-lease-time 3600; </span></span>
<span class="line"><span>max-lease-time 7200;</span></span>
<span class="line"><span>authoritative;</span></span></code></pre></div><p>5、 现在定义一个子网，这里我们为 <code>192.168.10.0/24</code> 局域网设置 DHCP （请使用适用你情况的参数）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>subnet 192.168.10.0 netmask 255.255.255.0 {</span></span>
<span class="line"><span>option routers                  192.168.10.1;</span></span>
<span class="line"><span>option subnet-mask              255.255.255.0;</span></span>
<span class="line"><span>option domain-search            &quot;tecmint.lan&quot;;</span></span>
<span class="line"><span>option domain-name-servers      192.168.10.1;</span></span>
<span class="line"><span>range   192.168.10.10   192.168.10.100;</span></span>
<span class="line"><span>range   192.168.10.110   192.168.10.200;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="步骤-3-在-dhcp-客户端上配置静态地址" tabindex="-1">步骤 3：在 DHCP 客户端上配置静态地址 <a class="header-anchor" href="#步骤-3-在-dhcp-客户端上配置静态地址" aria-label="Permalink to “步骤 3：在 DHCP 客户端上配置静态地址”">​</a></h3><p>6、 要给特定的客户机分配一个固定的（静态）的 IP，你需要显式将这台机器的 MAC 地址以及静态分配的地址添加到下面这部分。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>host centos-node {</span></span>
<span class="line"><span>hardware ethernet 00:f0:m4:6y:89:0g;</span></span>
<span class="line"><span>fixed-address 192.168.10.105;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>host fedora-node {</span></span>
<span class="line"><span>hardware ethernet 00:4g:8h:13:8h:3a;</span></span>
<span class="line"><span>fixed-address 192.168.10.106;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存并关闭文件。</p><p>7、 接下来，启动 DHCP 服务，并让它下次开机自启动，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>------------ SystemD ------------ </span></span>
<span class="line"><span>$ sudo systemctl start isc-dhcp-server.service</span></span>
<span class="line"><span>$ sudo systemctl enable isc-dhcp-server.service</span></span>
<span class="line"><span>------------ SysVinit ------------ </span></span>
<span class="line"><span>$ sudo service isc-dhcp-server.service start</span></span>
<span class="line"><span>$ sudo service isc-dhcp-server.service enable</span></span></code></pre></div><p>8、 接下来不要忘记允许 DHCP 服务（DHCP 守护进程监听 67 UDP 端口）的防火墙权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ufw allow  67/udp</span></span>
<span class="line"><span>$ sudo ufw reload</span></span>
<span class="line"><span>$ sudo ufw show</span></span></code></pre></div><h3 id="步骤-4-配置-dhcp-客户端" tabindex="-1">步骤 4：配置 DHCP 客户端 <a class="header-anchor" href="#步骤-4-配置-dhcp-客户端" aria-label="Permalink to “步骤 4：配置 DHCP 客户端”">​</a></h3><p>9、 此时，你可以将客户端计算机配置为自动从 DHCP 服务器接收 IP 地址。</p><p>登录到客户端并编辑以太网接口的配置文件（注意接口名称/号码）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/network/interfaces</span></span></code></pre></div><p>定义如下选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>auto  eth0</span></span>
<span class="line"><span>iface eth0 inet dhcp</span></span></code></pre></div><p>保存文件并退出。重启网络服务（或重启系统）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>------------ SystemD ------------ </span></span>
<span class="line"><span>$ sudo systemctl restart networking</span></span>
<span class="line"><span>------------ SysVinit ------------ </span></span>
<span class="line"><span>$ sudo service networking restart</span></span></code></pre></div><p>另外你也可以使用 GUI 来在进行设置，如截图所示（在 Fedora 25 桌面中）设置将方式设为自动（DHCP）。</p>`,27)),a("p",null,[i(e,{href:"http://www.tecmint.com/wp-content/uploads/2017/03/Set-DHCP-Network-in-Fedora.png"},{default:t(()=>[...s[6]||(s[6]=[a("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/03/Set-DHCP-Network-in-Fedora.png",alt:"Set DHCP Network in Fedora"},null,-1)])]),_:1})]),s[23]||(s[23]=a("p",null,[a("em",null,"在 Fedora 中设置 DHCP 网络")],-1)),s[24]||(s[24]=a("p",null,"此时，如果所有设置完成了，你的客户端应该可以自动从 DHCP 服务器接收 IP 地址了。",-1)),s[25]||(s[25]=a("p",null,"就是这样了！在本篇教程中，我们向你展示了如何在 Ubuntu/Debian 设置 DHCP 服务器。在反馈栏中分享你的想法。如果你正在使用基于 Fedora 的发行版，请阅读如何在 CentOS/RHEL 中设置 DHCP 服务器。",-1)),s[26]||(s[26]=a("hr",null,null,-1)),s[27]||(s[27]=a("p",null,"作者简介：",-1)),s[28]||(s[28]=a("p",null,"Aaron Kili 是 Linux 和 F.O.S.S 爱好者，将来的 Linux SysAdmin 和 web 开发人员，目前是 TecMint 的内容创建者，他喜欢用电脑工作，并坚信分享知识。",-1)),s[29]||(s[29]=a("hr",null,null,-1)),a("p",null,[s[8]||(s[8]=n("via: ",-1)),i(e,{href:"http://www.tecmint.com/install-dhcp-server-in-ubuntu-debian/"},{default:t(()=>[...s[7]||(s[7]=[n("http://www.tecmint.com/install-dhcp-server-in-ubuntu-debian/",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=n("作者：",-1)),i(e,{href:"http://www.tecmint.com/author/aaronkili/"},{default:t(()=>[...s[9]||(s[9]=[n("Aaron Kili",-1)])]),_:1}),s[13]||(s[13]=n(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[10]||(s[10]=[n("geekpi",-1)])]),_:1}),s[14]||(s[14]=n(" 校对：",-1)),i(e,{href:"https://github.com/jasminepeng"},{default:t(()=>[...s[11]||(s[11]=[n("jasminepeng",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[n("Linux中国",-1)])]),_:1}),s[19]||(s[19]=n(" 荣誉推出",-1))])])}const m=p(u,[["render",h]]);export{f as __pageData,m as default};
